def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = []
    opp = []
    total_c = 0
    for item in history:
        a, b = item
        my.append(a)
        opp.append(b)
        if b == 'C':
            total_c += 1

    last_me = my[-1]
    last_opp = opp[-1]
    opp_total_d = n - total_c

    last5_c = 0
    for i in range(max(0, n - 5), n):
        if opp[i] == 'C':
            last5_c += 1

    last10_c = 0
    for i in range(max(0, n - 10), n):
        if opp[i] == 'C':
            last10_c += 1

    last20_c = 0
    for i in range(max(0, n - 20), n):
        if opp[i] == 'C':
            last20_c += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            my_d_streak += 1
        else:
            break

    copy_m = 0
    copy_t = 0
    start_copy = 1
    if n > 20:
        start_copy = n - 20
    for i in range(start_copy, n):
        copy_t += 1
        if my[i - 1] == opp[i]:
            copy_m += 1
    copy_rate = 1.0
    if copy_t > 0:
        copy_rate = copy_m / copy_t

    nonpunish = 0
    punish = 0
    start_lag = 0
    if n > 40:
        start_lag = n - 40
    for i in range(start_lag, n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                nonpunish += 1
            else:
                punish += 1

    if total_c == 0 and n >= 5:
        return 'D'
    if last10_c == 0 and n >= 5:
        return 'D'

    if n >= 10:
        recent10 = opp[n - 10:]
        c10 = 0
        for x in recent10:
            if x == 'C':
                c10 += 1
        if 4 <= c10 <= 7:
            for p in (2, 3, 4, 5):
                ok = True
                for i in range(p, 10):
                    if recent10[i] != recent10[i - p]:
                        ok = False
                        break
                if ok and copy_rate <= 0.70 and opp_total_d >= 2:
                    return 'D'

    if opp_total_d == 0 and n >= 15 and last_opp == 'C' and last_me == 'C':
        return 'D'

    if last_me == 'D' and last_opp == 'C':
        if opp_total_d == 0 and nonpunish >= 1 and my_d_streak < 12:
            return 'D'
        if nonpunish >= 3 and nonpunish > punish + 1 and my_d_streak < 8:
            return 'D'
        return 'C'

    if last_opp == 'D' and last_me == 'C':
        if opp_d_streak <= 5 and (n <= 4 or last10_c >= 0.50 or last20_c >= 0.45):
            return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'D':
        if opp_d_streak <= 5 and (n <= 12 or last20_c >= 0.30 or copy_rate >= 0.60):
            return 'C'
        if last10_c >= 0.65 and opp_d_streak <= 8:
            return 'C'
        return 'D'

    if last_opp == 'C' and last_me == 'C':
        if opp_total_d == 0 and n >= 15:
            return 'D'
        if nonpunish >= 3 and nonpunish > punish + 1 and last10_c >= 0.60:
            return 'D'
        if last10_c >= 0.80 and copy_rate <= 0.55:
            return 'D'
        if last10_c >= 0.70 and punish == 0 and nonpunish >= 1:
            return 'D'
        return 'C'

    if last10_c >= 0.60:
        if last_opp == 'C':
            return 'C'
        return 'D'

    if last10_c >= 0.40:
        if last_opp == 'C':
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if rng.random() < 0.60:
            return 'D'
        return 'C'

    if rng.random() < 0.85:
        return 'D'
    return 'C'
